MASK24 = (1 << 24) - 1
MASK32 = (1 << 32) - 1
M64 = (1 << 64) - 1

def ip_cksum(data):
    total = 0
    for i in range(0, len(data) - 1, 2):
        total += (data[i] << 8) | data[i + 1]
    if len(data) % 2:
        total += data[-1] << 8
    while total >> 16:
        total = (total & 0xffff) + (total >> 16)
    return (~total) & 0xffff

def icrc(frame):
    # frame without trailing ICRC is frame[:-4]; frame includes 4 trailing bytes placeholder
    ip = frame[14:]
    ip_len = (ip[2] << 8) | ip[3]
    crc = bytearray(b'\xff' * 8 + bytes(ip[:ip_len - 4]))
    crc[9] = 255; crc[16] = 255; crc[18] = 255; crc[19] = 255
    crc[34] = 255; crc[35] = 255; crc[40] = 255
    return zlib.crc32(bytes(crc)) & MASK32

