/* Offline RoCEv2 packet codec: strict ingress validation and canonical egress
 * sealing.  The rules implemented here are exactly those of PROTOCOL.md. */
#include "epic_clean.h"

#include <arpa/inet.h>
#include <stdlib.h>
#include <string.h>

#define ETHERTYPE_IPV4 0x0800
#define ROCE_OPCODE_DATA 0x04u
#define ROCE_OPCODE_ACK 0x11u

static uint32_t crc32_table[256];
static bool crc32_ready;

void epic_crc32_init(void) {
    if (crc32_ready) {
        return;
    }
    const uint32_t poly = 0xedb88320u;
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? poly : 0u);
        }
        crc32_table[i] = crc;
    }
    crc32_ready = true;
}

static uint32_t epic_crc32(const void *data, size_t len) {
    epic_crc32_init();
    const uint8_t *buf = data;
    uint32_t crc = 0xffffffffu;
    while (len--) {
        crc = (crc >> 8) ^ crc32_table[(crc ^ *buf++) & 0xffu];
    }
    return crc ^ 0xffffffffu;
}

uint16_t epic_ipv4_checksum(const void *data, size_t len) {
    const uint8_t *bytes = data;
    uint32_t sum = 0;
    while (len > 1) {
        sum += (uint16_t)((bytes[0] << 8) | bytes[1]);
        bytes += 2;
        len -= 2;
    }
    if (len) {
        sum += (uint16_t)(bytes[0] << 8);
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return htons((uint16_t)~sum);
}

/* ICRC input: eight 0xff bytes followed by the IPv4 datagram without the
 * trailing ICRC, with TOS, TTL, IPv4 checksum, UDP checksum and the QPN top
 * byte masked to 0xff.  Result is the standard reflected CRC32. */
uint32_t epic_compute_icrc(const uint8_t *frame, size_t frame_len) {
    if (frame_len < EPIC_ETH_LEN + EPIC_IP_LEN + EPIC_ICRC_LEN) {
        return 0;
    }
    const epic_ipv4_t *ip = (const epic_ipv4_t *)(frame + EPIC_ETH_LEN);
    size_t ip_len = ntohs(ip->total_length);
    if (ip_len < EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN + EPIC_ICRC_LEN ||
        EPIC_ETH_LEN + ip_len != frame_len) {
        return 0;
    }
    uint8_t buf[EPIC_MAX_FRAME];
    size_t crc_len = 8 + ip_len - EPIC_ICRC_LEN;
    if (crc_len > sizeof(buf)) {
        return 0;
    }
    memset(buf, 0xff, 8);
    memcpy(buf + 8, frame + EPIC_ETH_LEN, ip_len - EPIC_ICRC_LEN);
    buf[8 + 1] = 0xff;                    /* IPv4 TOS */
    buf[8 + 8] = 0xff;                    /* IPv4 TTL */
    buf[8 + 10] = 0xff;                   /* IPv4 checksum */
    buf[8 + 11] = 0xff;
    buf[8 + 20 + 6] = 0xff;               /* UDP checksum */
    buf[8 + 20 + 7] = 0xff;
    buf[8 + 20 + 8 + 4] = 0xff;           /* BTH QPN top byte */
    return epic_crc32(buf, crc_len);
}

static uint16_t load16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t load24(const uint8_t *p) {
    return ((uint32_t)p[0] << 16) | ((uint32_t)p[1] << 8) | p[2];
}
static uint32_t load32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) |
           p[3];
}

bool epic_wire_validate(const uint8_t *frame, size_t frame_len, size_t words,
                        epic_wire_t *out) {
    const size_t ip_off = EPIC_ETH_LEN;
    const size_t udp_off = ip_off + EPIC_IP_LEN;
    const size_t bth_off = udp_off + EPIC_UDP_LEN;

    out->is_ack = false;
    out->psn = 0;
    out->qpn = 0;
    out->payload = NULL;
    out->payload_len = 0;

    if (!frame || !out) {
        return false;
    }
    /* Ethernet: IPv4 only, no FCS or padding is present. */
    if (frame_len < EPIC_ETH_LEN + EPIC_IP_LEN + EPIC_UDP_LEN + EPIC_BTH_LEN +
                       EPIC_ICRC_LEN) {
        return false;
    }
    if (load16(frame + 12) != ETHERTYPE_IPV4) {
        return false;
    }
    const uint8_t *ip = frame + ip_off;
    if (ip[0] != 0x45) {                      /* version 4, IHL 20, no options */
        return false;
    }
    size_t ip_len = load16(ip + 2);
