static size_t build_base(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn,
                         uint8_t opcode, size_t body_len) {
    size_t total = EPIC_DATA_HEAD + body_len + EPIC_ICRC_LEN;
    if (frame_cap < total || total > sizeof(((epic_eth_t *)0)) * 0 + EPIC_MAX_FRAME) {
        return 0;
    }
    memset(frame, 0, total);
    epic_eth_t *eth = (epic_eth_t *)frame;
    eth->dst_mac[0] = 0x02;
    eth->dst_mac[5] = (uint8_t)(rank + 1);
    eth->src_mac[0] = 0x02;
    eth->src_mac[1] = 0x01;
    eth->src_mac[5] = (uint8_t)(rank + 1);
    eth->ether_type = htons(ETHERTYPE_IPV4);

    epic_ipv4_t *ip = (epic_ipv4_t *)(frame + EPIC_ETH_LEN);
    ip->version_ihl = 0x45;
    ip->tos = 0;
    ip->total_length = htons((uint16_t)(total - EPIC_ETH_LEN));
    ip->id = htons(0x1111);
    ip->flags_frag_off = htons(0x4000);
    ip->ttl = 64;
    ip->protocol = 17;
    ip->src_ip = htonl(0x0a000065u + (uint32_t)rank);
    ip->dst_ip = htonl(0x0a000001u + (uint32_t)rank);
    ip->checksum = epic_ipv4_checksum(ip, EPIC_IP_LEN);

    epic_udp_t *udp = (epic_udp_t *)((uint8_t *)ip + EPIC_IP_LEN);
    udp->src_port = htons(EPIC_ROCE_UDP_PORT);
    udp->dst_port = htons(EPIC_ROCE_UDP_PORT);
    udp->length = htons((uint16_t)(total - EPIC_ETH_LEN - EPIC_IP_LEN));
    udp->checksum = 0;

    epic_bth_t *bth = (epic_bth_t *)((uint8_t *)udp + EPIC_UDP_LEN);
    bth->opcode = opcode;
    bth->se_m_pad = 0;
    bth->pkey = htons(0xffff);
    bth->qpn = htonl((uint32_t)(0x100 + rank) & EPIC_PSN_MASK);
    bth->apsn = htonl((psn & EPIC_PSN_MASK) |
                      (opcode == ROCE_OPCODE_DATA ? 0x80000000u : 0u));
    return total;
}

size_t epic_build_data(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn,
                       const uint8_t *payload, size_t payload_bytes) {
    if (payload_bytes > EPIC_MAX_PAYLOAD_BYTES ||
        (payload_bytes > 0 && !payload) || payload_bytes % 4 != 0) {
        return 0;
    }
    size_t total = build_base(frame, frame_cap, rank, psn, ROCE_OPCODE_DATA,
                              payload_bytes);
    if (!total) {
        return 0;
    }
    if (payload_bytes) {
        memcpy(frame + EPIC_DATA_HEAD, payload, payload_bytes);
    }
    uint32_t icrc = htoepic_icrc(epic_compute_icrc(frame, total));
    memcpy(frame + total - EPIC_ICRC_LEN, &icrc, EPIC_ICRC_LEN);
    return total;
}

size_t epic_build_ack(uint8_t *frame, size_t frame_cap, int rank, uint32_t psn) {
    size_t total = build_base(frame, frame_cap, rank, psn, ROCE_OPCODE_ACK,
                              EPIC_AETH_LEN);
    if (!total) {
        return 0;
    }
    uint32_t aeth = htonl(0x1fu << 24 | ((psn + 1u) & EPIC_PSN_MASK));
    memcpy(frame + EPIC_DATA_HEAD, &aeth, EPIC_AETH_LEN);
    uint32_t icrc = htoepic_icrc(epic_compute_icrc(frame, total));
    memcpy(frame + total - EPIC_ICRC_LEN, &icrc, EPIC_ICRC_LEN);
    return total;
}
