static void *xalloc(size_t n) { return calloc(n ? n : 1, 1); }

void *epic_open(int primitive, int mode, int root, uint32_t count, uint32_t words,
                uint32_t capacity, uint32_t start, uint32_t trace_limit) {
    epic_ctx_t *ctx = xalloc(sizeof(*ctx));
    if (!ctx) {
        return NULL;
    }
    ctx->kind = primitive;
    ctx->mode = mode;
    ctx->root = root;
    ctx->K = count;
    ctx->D = words;
    ctx->N = capacity;
    ctx->start = start & 0x00ffffffu;
    ctx->m = count / 4;
    ctx->req_mask = (primitive == (int)EPIC_PRIM_BCAST)
                        ? (uint8_t)(1u << (unsigned)root)
                        : (uint8_t)0xfu;
    size_t stride;
    if (primitive == (int)EPIC_PRIM_ALLGATHER) {
        stride = 16 * (size_t)words;
    } else if (primitive == (int)EPIC_PRIM_BARRIER) {
        stride = 0;
    } else {
        stride = 4 * (size_t)words;
    }
    ctx->stride = stride;
    ctx->used = xalloc(capacity);
    ctx->slot_p = xalloc(capacity * sizeof(*ctx->slot_p));
    ctx->slot_mask = xalloc(capacity);
    ctx->pool = xalloc((size_t)capacity * (stride ? stride : 1));
    init_outc_decl(ctx);
    if (!ctx->used || !ctx->slot_p || !ctx->slot_mask || !ctx->pool) {
        epic_close(ctx);
        return NULL;
    }
    ctx->budget = -1; /* unlimited until a budget event says otherwise */
    epic_sha256_init(&ctx->sha);
    if (trace_limit > EPIC_TRACE_MAX) {
        trace_limit = EPIC_TRACE_MAX;
    }
    if (trace_limit) {
        ctx->trace = xalloc((size_t)trace_limit * sizeof(*ctx->trace));
        if (!ctx->trace) {
            epic_close(ctx);
            return NULL;
        }
        ctx->trace_limit = trace_limit;
    }
    return ctx;
}

void epic_close(void *context) {
    epic_ctx_t *ctx = context;
    if (!ctx) {
        return;
    }
    free(ctx->used);
    free(ctx->slot_p);
    free(ctx->slot_mask);
    free(ctx->pool);
    free(ctx->trace);
    free(ctx);
}

int epic_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    collector_ingress(context, rank, frame, length);
    return 0;
