/* Four-port offline collective collector.
 *
 * This is the finite packet-replay implementation of the contract in
 * PROTOCOL.md: no socket, NIC, GPU or switch is touched.  Ingress frames are
 * validated strictly, admitted into a bounded retention pool, aggregated per
 * collective, and drained through a deterministic egress priority that owns
 * cumulative upstream acknowledgment, mode-2 reliability translation, mode-3
 * result retransmission and local backpressure. */
#include "switch_ctx.h"

#include <stdlib.h>
#include <string.h>

#define PSN_MASK EPIC_PSN_MASK
#define ALL_MASK 0xfu

/* ------------------------------------------------------------------ *
 * Sequence-space mappings
 * ------------------------------------------------------------------ */

static int ordinal_excluding(int dst, int src) {
    return src - (dst < src ? 1 : 0);
}

static int rank_from_ordinal(int dst, int ordinal) {
    int n = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        if (r == dst) {
            continue;
        }
        if (n == ordinal) {
            return r;
        }
        n++;
    }
    return 0;
}

void epic_init_outc(epic_ctx_t *ctx) {
    uint32_t K = ctx->K;
    for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
        uint32_t n;
        switch ((epic_primitive_t)ctx->kind) {
        case EPIC_PRIM_ALLREDUCE:
        case EPIC_PRIM_BARRIER:
            n = K;
            if (ctx->kind == EPIC_PRIM_BARRIER) {
                n = 1; /* barrier is a single segment for every rank */
            }
            break;
        case EPIC_PRIM_REDUCE:
            n = (d == ctx->root) ? K : 0;
            break;
        case EPIC_PRIM_BCAST:
            n = (d == ctx->root) ? 0 : K;
            break;
        case EPIC_PRIM_ALLGATHER:
            n = 3 * K;
            break;
        case EPIC_PRIM_REDUCESCATTER:
            n = K / 4;
            break;
        default:
            n = 0;
            break;
        }
        ctx->outc[d] = n;
    }
}

/* Logical input segment owning receiver d's output record q. */
static uint32_t rec_p(const epic_ctx_t *ctx, int d, uint32_t q) {
    switch ((epic_primitive_t)ctx->kind) {
    case EPIC_PRIM_ALLGATHER:
        return q / 3;
    case EPIC_PRIM_REDUCESCATTER:
        return (uint32_t)d * ctx->m + q;
    case EPIC_PRIM_BARRIER:
        return 0;
    default:
        (void)d;
        return q;
    }
}

/* Source whose value receiver d's output record q carries (allgather only). */
static int rec_src(const epic_ctx_t *ctx, int d, uint32_t q) {
    if (ctx->kind == (int)EPIC_PRIM_ALLGATHER) {
        return rank_from_ordinal(d, (int)(q % 3));
    }
    (void)d;
    (void)q;
    return -1;
}

/* ------------------------------------------------------------------ *
 * Retention pool
 * ------------------------------------------------------------------ */

uint8_t *epic_slot_base(const epic_ctx_t *ctx, uint32_t index) {
    return ctx->pool + (size_t)index * ctx->stride;
}

int epic_slot_index(const epic_ctx_t *ctx, uint32_t p, uint32_t *idx) {
    uint32_t i = p % ctx->N;
    *idx = i;
    return ctx->used[i] && ctx->slot_p[i] == p;
}

static int complete_at(const epic_ctx_t *ctx, uint32_t p) {
    uint32_t i;
    if (!epic_slot_index(ctx, p, &i)) {
        return 0;
    }
    return ctx->slot_mask[i] == ctx->req_mask;
}

/* ------------------------------------------------------------------ *
 * Acknowledgment eligibility
 * ------------------------------------------------------------------ */

 * ------------------------------------------------------------------ */

static uint32_t eligible_prefix(const epic_ctx_t *ctx, int r) {
    uint32_t R = ctx->R[r];
    if (ctx->mode == (int)EPIC_MODE_TERMINATION) {
        return R; /* accepted contributions are safe immediately */
    }
    const uint32_t *a = ctx->down;
    switch ((epic_primitive_t)ctx->kind) {
    case EPIC_PRIM_ALLREDUCE:
    case EPIC_PRIM_BARRIER:
        return R < a[r] ? R : a[r];
    case EPIC_PRIM_REDUCE:
        return R < a[ctx->root] ? R : a[ctx->root];
    case EPIC_PRIM_BCAST: {
        if (r != ctx->root) {
            return 0;
        }
        uint32_t v = R;
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d != ctx->root && a[d] < v) {
                v = a[d];
            }
        }
        return v;
    }
    case EPIC_PRIM_REDUCESCATTER: {
        uint32_t g = 0;
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            uint32_t t = a[d] < ctx->m ? a[d] : ctx->m;
            g += t;
            if (t < ctx->m) {
                break;
            }
        }
        return R < g ? R : g;
    }
    case EPIC_PRIM_ALLGATHER: {
        uint32_t v = R;
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d == r) {
                continue;
            }
            int o = ordinal_excluding(d, r);
            long n = (long)a[d] - o + 2;
            uint32_t cnt = n > 0 ? (uint32_t)(n / 3) : 0;
            if (cnt < v) {
                v = cnt;
            }
        }
        return v;
    }
    default:
        return 0;
    }
}

/* Every output record belonging to input p acknowledged by its receiver? */
static int outputs_acked(const epic_ctx_t *ctx, uint32_t p) {
    const uint32_t *a = ctx->down;
    switch ((epic_primitive_t)ctx->kind) {
    case EPIC_PRIM_ALLREDUCE:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (a[d] < p + 1) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_REDUCE:
        return a[ctx->root] >= p + 1;
    case EPIC_PRIM_BCAST:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (d != ctx->root && a[d] < p + 1) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_BARRIER:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (a[d] < 1) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < EPIC_STAR4_HOSTS; d++) {
            if (a[d] < 3 * p + 3) {
                return 0;
            }
        }
        return 1;
    case EPIC_PRIM_REDUCESCATTER: {
        int d = (int)(p / ctx->m);
        return a[d] >= p % ctx->m + 1;
    }
    default:
        return 0;
    }
}

static int sources_upacked(const epic_ctx_t *ctx, uint32_t p) {
    int first = (ctx->kind == (int)EPIC_PRIM_BCAST) ? ctx->root : 0;
    int last = (ctx->kind == (int)EPIC_PRIM_BCAST) ? ctx->root + 1 : EPIC_STAR4_HOSTS;
    for (int r = first; r < last; r++) {
        if (ctx->up[r] <= p) {
            return 0;
        }
    }
    return 1;
}

static void release_slot(epic_ctx_t *ctx, uint32_t p) {
    uint32_t i;
    if (!epic_slot_index(ctx, p, &i)) {
        return;
    }
    ctx->used[i] = 0;
    ctx->slot_mask[i] = 0;
    ctx->slot_p[i] = 0;
    ctx->occupied--;
}

static void retire(epic_ctx_t *ctx) {
    while (ctx->retired < ctx->K) {
        uint32_t p = ctx->retired;
        if (!complete_at(ctx, p) || !outputs_acked(ctx, p) || !sources_upacked(ctx, p)) {
            break;
        }
        release_slot(ctx, p);
        ctx->retired = p + 1;
    }
}

/* ------------------------------------------------------------------ *
 * Egress transcript (SHA-256 of rank byte, little-endian length, frame)
 * ------------------------------------------------------------------ */

static int transport(epic_ctx_t *ctx, int rank, const uint8_t *frame, size_t len) {
    if (ctx->budget == 0) {
        return 0;
    }
    if (ctx->budget > 0) {
        ctx->budget--;
    }
    uint8_t head[5];
    head[0] = (uint8_t)rank;
    head[1] = (uint8_t)len;
    head[2] = (uint8_t)(len >> 8);
    head[3] = (uint8_t)(len >> 16);
    head[4] = (uint8_t)(len >> 24);
    epic_sha256_update(&ctx->sha, head, 5);
    epic_sha256_update(&ctx->sha, frame, len);
    ctx->packets++;
    ctx->bytes += len;
    if (ctx->trace && ctx->trace_n < ctx->trace_limit) {
        ctx->trace[ctx->trace_n].rank = rank;
        ctx->trace[ctx->trace_n].len = len;
        memcpy(ctx->trace[ctx->trace_n].frame, frame, len);
        ctx->trace_n++;
    }
    return 1;
}

static int send_upstream_ack(epic_ctx_t *ctx, int r, uint32_t prefix) {
    uint32_t psn = (ctx->start + prefix - 1) & PSN_MASK;
    size_t len = epic_build_ack(ctx->frame, sizeof(ctx->frame), r, psn);
    if (!len) {
        return 0;
    }
    if (!transport(ctx, r, ctx->frame, len)) {
        return 0;
    }
    ctx->c_tx_ack++;
    return 1;
}

static const uint8_t *result_payload(epic_ctx_t *ctx, int d, uint32_t q,
                                     uint32_t p, size_t *out_len) {
    uint32_t i;
    if (!epic_slot_index(ctx, p, &i)) {
        return NULL;
    }
    uint8_t *base = epic_slot_base(ctx, i);
    if (ctx->kind == (int)EPIC_PRIM_BARRIER) {
        *out_len = 0;
        return base;
    }
    if (ctx->kind == (int)EPIC_PRIM_BCAST) {
        *out_len = 4 * (size_t)ctx->D;
        return base;
    }
    if (ctx->kind == (int)EPIC_PRIM_ALLGATHER) {
        int s = rec_src(ctx, d, q);
        *out_len = 4 * (size_t)ctx->D;
        return base + (size_t)s * 4 * (size_t)ctx->D;
    }
    /* Running aggregate: network order on the wire. */
    uint32_t words = ctx->D;
    uint8_t *out = ctx->scratch;
    const uint32_t *src = (const uint32_t *)base;
    for (uint32_t j = 0; j < words; j++) {

    for (uint32_t j = 0; j < words; j++) {
        uint32_t v = src[j];
        out[j * 4 + 0] = (uint8_t)(v >> 24);
        out[j * 4 + 1] = (uint8_t)(v >> 16);
        out[j * 4 + 2] = (uint8_t)(v >> 8);
        out[j * 4 + 3] = (uint8_t)v;
    }
    *out_len = 4 * (size_t)words;
    return out;
}

static int send_result(epic_ctx_t *ctx, int d, uint32_t q) {
    uint32_t p = rec_p(ctx, d, q);
    size_t len = 0;
    const uint8_t *payload = result_payload(ctx, d, q, p, &len);
    if (!payload && len) {
        return 0;
    }
    size_t flen = epic_build_data(ctx->frame, sizeof(ctx->frame), d,
                                  (ctx->start + q) & PSN_MASK, payload, len);
    if (!flen) {
        return 0;
    }
    if (!transport(ctx, d, ctx->frame, flen)) {
        return 0;
    }
    ctx->c_tx_data++;
    return 1;
}

static int record_ready(const epic_ctx_t *ctx, int d, uint32_t q) {
    return q < ctx->outc[d] && complete_at(ctx, rec_p(ctx, d, q));
}

/* One service opportunity: pending upstream ACKs, then (retry only) the
 * selected receiver's sent-but-unacknowledged results, then new results. */
void epic_service(epic_ctx_t *ctx, int retry_rank) {
    int stopped = 0;
    for (int r = 0; r < EPIC_STAR4_HOSTS; r++) {
        uint32_t e = eligible_prefix(ctx, r);
        if ((e > ctx->up[r] || ctx->repeat[r]) && e > 0) {
            if (send_upstream_ack(ctx, r, e)) {
                ctx->up[r] = e;
                ctx->repeat[r] = 0;
            } else {
                ctx->c_fail++;
                stopped = 1;
                break;
            }
        }
    }
    if (!stopped && retry_rank >= 0) {
        int d = retry_rank;
        for (uint32_t q = ctx->down[d]; q < ctx->sent[d]; q++) {
            if (!send_result(ctx, d, q)) {
                ctx->c_fail++;
                stopped = 1;
                break;
            }
        }
    }
    if (!stopped) {
        for (int d = 0; d < EPIC_STAR4_HOSTS && !stopped; d++) {
            while (record_ready(ctx, d, ctx->sent[d])) {
                if (!send_result(ctx, d, ctx->sent[d])) {
                    ctx->c_fail++;
                    stopped = 1;
                    break;
                }
                ctx->sent[d]++;
            }
        }
    }
    retire(ctx);
}

/* ------------------------------------------------------------------ *
 * Ingress
 * ------------------------------------------------------------------ */

static int endpoint_ok(const uint8_t *frame, uint32_t qpn, int rank) {
    uint8_t host_mac[6] = {2, 0, 0, 0, 0, 0};
    uint8_t sw_mac[6] = {2, 1, 0, 0, 0, 0};
    host_mac[5] = (uint8_t)(rank + 1);
    sw_mac[5] = (uint8_t)(rank + 1);
    if (memcmp(frame + 0, sw_mac, 6) != 0 || memcmp(frame + 6, host_mac, 6) != 0) {
        return 0;
    }
    uint32_t src_ip = ((uint32_t)frame[26] << 24) | ((uint32_t)frame[27] << 16) |
                      ((uint32_t)frame[28] << 8) | frame[29];
    uint32_t dst_ip = ((uint32_t)frame[30] << 24) | ((uint32_t)frame[31] << 16) |
                      ((uint32_t)frame[32] << 8) | frame[33];
    if (src_ip != 0x0a000001u + (uint32_t)rank ||
        dst_ip != 0x0a000065u + (uint32_t)rank) {
        return 0;
    }
    return qpn == (uint32_t)(0x200 + rank);
}

static void advance_prefix(epic_ctx_t *ctx, int r) {
    uint32_t bit = 1u << r;
    while (ctx->R[r] < ctx->K) {
        uint32_t i = ctx->R[r] % ctx->N;
        if (!ctx->used[i] || ctx->slot_p[i] != ctx->R[r] ||
            !(ctx->slot_mask[i] & bit)) {
            break;
        }
        ctx->R[r]++;
    }
}

static void accept_contribution(epic_ctx_t *ctx, uint32_t i, int rank,
                                const uint8_t *payload, size_t len) {
    uint8_t *base = epic_slot_base(ctx, i);
    switch ((epic_primitive_t)ctx->kind) {
    case EPIC_PRIM_BCAST:
        memcpy(base, payload, len);
        break;
    case EPIC_PRIM_ALLGATHER:
        memcpy(base + (size_t)rank * 4 * (size_t)ctx->D, payload, len);
        break;
    case EPIC_PRIM_BARRIER:
        break;
    default: {
        uint32_t *agg = (uint32_t *)base;
        const uint8_t *src = payload;
        uint32_t first = (ctx->slot_mask[i] == 0);
        for (uint32_t j = 0; j < ctx->D; j++) {
            uint32_t v = ((uint32_t)src[j * 4] << 24) | ((uint32_t)src[j * 4 + 1] << 16) |
                         ((uint32_t)src[j * 4 + 2] << 8) | src[j * 4 + 3];
            if (first) {
                agg[j] = v;
            } else {
                agg[j] += v;
            }
        }
        break;
    }
    }
}

void collector_ingress(epic_ctx_t *ctx, int rank, const uint8_t *frame,
                       size_t length) {
    epic_wire_t w;
    if (!epic_wire_validate(frame, length, ctx->D, &w)) {
        ctx->c_wire++;
        return;
    }
    if (!endpoint_ok(frame, w.qpn, rank)) {
        ctx->c_endpoint++;
        return;

        return;
    }
    if (w.is_ack) {
        ctx->c_ack++;
        uint32_t n = (w.psn - ctx->start + 1) & PSN_MASK;
        if (n > ctx->down[rank] && n <= ctx->sent[rank]) {
            ctx->down[rank] = n;
        } else {
            ctx->c_ignore++;
        }
        epic_service(ctx, -1);
        return;
    }
