        ctx->c_endpoint++;
        return;
    }
    ctx->c_data++;
    uint32_t b = ctx->retired;
    if (p < b) {
        ctx->c_stale++;
        ctx->repeat[rank] = 1;
        epic_service(ctx, -1);
        return;
    }
    uint32_t window = b + ctx->N;
    if (window > ctx->K) {
        window = ctx->K;
    }
    if (p >= window) {
        ctx->c_block++;
        epic_service(ctx, -1);
        return;
    }
    uint32_t i = p % ctx->N;
    if (!ctx->used[i] || ctx->slot_p[i] != p) {
        if (ctx->used[i]) {
            ctx->c_overwrite++; /* unreachable: identities are retired first */
        }
        ctx->used[i] = 1;
        ctx->slot_p[i] = p;
        ctx->slot_mask[i] = 0;
        ctx->occupied++;
    }
    uint32_t bit = 1u << (unsigned)rank;
    if (ctx->slot_mask[i] & bit) {
        ctx->c_dup++;
        ctx->repeat[rank] = 1;
        epic_service(ctx, -1);
        return;
    }
    accept_contribution(ctx, i, rank, w.payload, w.payload_len);
    ctx->slot_mask[i] = (uint8_t)(ctx->slot_mask[i] | bit);
    ctx->c_accept++;
    advance_prefix(ctx, rank);
    epic_service(ctx, -1);
