#!/usr/bin/env python3
"""Pure-Python offline collector: the same PROTOCOL.md state machine as the C
library.  solver.py uses this only if compiling the C project is impossible;
behaviour and certificates are identical.  No I/O beyond CPU emulation."""
import hashlib
import struct
import zlib

from wire import NAMES, packet, payload as word_payload

MASK24 = 0x00FFFFFF
MASK32 = 0xFFFFFFFF
MASK64 = (1 << 64) - 1
FNV_OFFSET = 14695981039346656037
FNV_PRIME = 1099511628211


def _ipv4_checksum(header):
    total = 0
    for i in range(0, len(header) - 1, 2):
        total += (header[i] << 8) | header[i + 1]
    if len(header) % 2:
        total += header[-1] << 8
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _icrc(frame):
    ip_len = (frame[16] << 8) | frame[17]
    crc = bytearray(b'\xff' * 8 + bytes(frame[14:len(frame) - 4]))
    crc[9] = 255
    crc[16] = 255
    crc[18] = 255
    crc[19] = 255
    crc[34] = 255
    crc[35] = 255
    crc[40] = 255
    return zlib.crc32(bytes(crc)) & MASK32


def wire_validate(frame, words):
    """Return (is_ack, psn, qpn, payload) or None when the frame is
    wire-invalid.  Rules are exactly those of PROTOCOL.md."""
    flen = len(frame)
    if flen < 14 + 20 + 8 + 12 + 4:
        return None
    if (frame[12] << 8) | frame[13] != 0x0800:
        return None
    if frame[14] != 0x45:
        return None
    ip_len = (frame[16] << 8) | frame[17]
    if ip_len < 44 or 14 + ip_len != flen:
        return None
    if frame[23] != 17:
        return None
    if ((frame[20] << 8) | frame[21]) not in (0x0000, 0x4000):
        return None
    hdr = bytearray(frame[14:34])
    hdr[10] = 0
    hdr[11] = 0
    if ((frame[24] << 8) | frame[25]) != _ipv4_checksum(hdr):
        return None
    udp_len = (frame[38] << 8) | frame[39]
    if udp_len != ip_len - 20:
        return None
    if (frame[34] << 8 | frame[35]) != 4791 or (frame[36] << 8 | frame[37]) != 4791:
        return None
    if (frame[40] << 8) | frame[41]:
        return None
    if udp_len < 24 + 4:
        return None
    opcode = frame[42]
    if opcode not in (0x04, 0x11):
        return None
    if frame[43] != 0:
        return None
    if (frame[44] << 8 | frame[45]) != 0xFFFF:
        return None
    qpn = (frame[46] << 24) | (frame[47] << 16) | (frame[48] << 8) | frame[49]
    if qpn >> 24:
        return None
    apsn = (frame[50] << 24) | (frame[51] << 16) | (frame[52] << 8) | frame[53]
    psn = apsn & MASK24
    if (apsn >> 24) != (0x80 if opcode == 0x04 else 0x00):
        return None
    body_len = udp_len - 24 - 4
    if opcode == 0x11:
        if body_len != 4:
            return None
        aeth = (frame[54] << 24) | (frame[55] << 16) | (frame[56] << 8) | frame[57]
        if (aeth >> 24) != 0x1F or (aeth & MASK24) != (psn + 1) & MASK24:
            return None
        payload = b''
    else:
        if body_len != 4 * words:
            return None
        payload = bytes(frame[54:54 + body_len])
    stored = (frame[flen - 1] << 24) | (frame[flen - 2] << 16) | \
             (frame[flen - 3] << 8) | frame[flen - 4]
    if stored != _icrc(frame):
        return None
    return (opcode == 0x11, psn, qpn & MASK24, payload)


def _ordinal_excluding(dst, src):
    return src - (1 if dst < src else 0)


def _rank_from_ordinal(dst, ordinal):
    n = 0
    for r in range(4):
        if r == dst:
            continue
        if n == ordinal:
            return r
        n += 1
    return 0


class Collector(object):
    def __init__(self, case):
        self.kind = case['primitive']
        self.mode = case['mode']
        self.root = case['root']
        self.K = case['segments']
        self.D = case['words']
        self.N = case['capacity']
        self.start = case['start'] & MASK24
        self.m = self.K // 4
        self.req_mask = (1 << self.root) if self.kind == 'broadcast' else 0xF
        self.outc = self._outc()
        self.b = 0
        self.slots = {}
        self.R = [0, 0, 0, 0]
        self.sent = [0, 0, 0, 0]
        self.down = [0, 0, 0, 0]
        self.up = [0, 0, 0, 0]
        self.repeat = [0, 0, 0, 0]
        self.c = [0] * 14
        self.budget = -1
        self.tape = hashlib.sha256()
        self.packets = 0
        self.nbytes = 0
