        if self.kind == 'reducescatter':
            return d * self.m + q
        if self.kind == 'barrier':
            return 0
        return q

    def _rec_src(self, d, q):
        if self.kind == 'allgather':
            return _rank_from_ordinal(d, q % 3)
        return -1

    def _complete(self, p):
        slot = self.slots.get(p)
        return slot is not None and slot[0] == self.req_mask

    # ---------------- egress ----------------
    def _transport(self, rank, frame):
        if self.budget == 0:
            return False
        if self.budget > 0:
            self.budget -= 1
        self.tape.update(bytes((rank,)) + struct.pack('<I', len(frame)) + frame)
        self.packets += 1
        self.nbytes += len(frame)
        if self.trace and len(self.trace) < self.trace_limit:
            self.trace.append({'rank': rank, 'hex': frame.hex()})
        return True

    def _send_ack(self, r, prefix):
        frame = packet(r, (self.start + prefix - 1) & MASK24, ack=True,
                       outgoing=True)
        if not self._transport(r, frame):
            self.c[11] += 1
            return False
        self.c[3] += 1
        return True

    def _result_frame(self, d, q):
        p = self._rec_p(d, q)
        slot = self.slots[p]
        kind = self.kind
        if kind == 'barrier':
            body = b''
        elif kind == 'broadcast':
            body = slot[1]
        elif kind == 'allgather':
