        return ([self.b, len(self.slots)] + self.R + self.sent + self.down +
                self.up + [c[0], c[1], c[2], c[3], c[4], c[5], c[6], c[7],
                           c[8], c[9], c[10], c[11], 0, 0])

    def digest(self):
        h = FNV_OFFSET
        fold = lambda value: ((h ^ value) * FNV_PRIME) & MASK64
        for p in sorted(self.slots):
            if p < self.b or p >= min(self.K, self.b + self.N):
                continue
