void epic_close(void *context) {
    epic_ctx_t *ctx = context;
    if (!ctx) {
        return;
    }
    free(ctx->used);
    free(ctx->slot_p);
    free(ctx->slot_mask);
    free(ctx->pool);
    free(ctx->trace);
    free(ctx);
