static uint32_t crc32_table[256];
static bool crc32_ready;

static void epic_crc32_init(void) {
    if (crc32_ready) {
        return;
    }
    const uint32_t poly = 0xedb88320u;
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1u) ? poly : 0u);
        }
        crc32_table[i] = crc;
    }
    crc32_ready = true;
}

static uint32_t epic_crc32(const void *data, size_t len) {
    epic_crc32_init();
    const uint8_t *buf = data;
    uint32_t crc = 0xffffffffu;
    while (len--) {
        crc = (crc >> 8) ^ crc32_table[(crc ^ *buf++) & 0xffu];
    }
    return crc ^ 0xffffffffu;
}

uint16_t epic_ipv4_checksum(const void *data, size_t len) {
    const uint8_t *bytes = data;
    uint32_t sum = 0;
    while (len > 1) {
        sum += (uint16_t)((bytes[0] << 8) | bytes[1]);
        bytes += 2;
        len -= 2;
    }
    if (len) {
        sum += (uint16_t)(bytes[0] << 8);
    }
    while (sum >> 16) {
        sum = (sum & 0xffffu) + (sum >> 16);
    }
    return htons((uint16_t)~sum);
